const NOMES = { Salmo: "Salmos", Oseias: "Oséias" };
const UM_CAPITULO = new Set(["Obadias", "Filemom", "2 João", "3 João", "Judas"]);

/**
 * "Gênesis 12.1-3; 15.1-6" → [{ livro, cap, de, capFim, ate, rotulo, ref }]
 * `de`/`ate` null = capítulo inteiro. `ref` é o formato que o leitor do app abre ("Gênesis 12:1").
 * O livro de um trecho vale para os seguintes até aparecer outro ("Romanos 3.28; 5.1; 8.1, 33-34").
 */
export function parseReferencias(texto) {
  const out = [];
  let livro = null;
  for (const parte of texto.split(";")) {
    let p = parte.replace(/\(.*?\)/g, "").trim();
    const m = p.match(/^((?:[1-3] )?[A-Za-zÀ-ÿ]+)\s+(\d.*)$/);
    if (m) {
      livro = NOMES[m[1]] || m[1];
      p = m[2];
    }
    let cap = null;
    for (const peca of p.split(",").map((s) => s.trim()).filter(Boolean)) {
      let c, de = null, cf, ate = null;
      const cruz = peca.match(/^(\d+)\.(\d+)\s*[–-]\s*(\d+)\.(\d+)$/); // 1.1–2.3
      const comCap = peca.match(/^(\d+)\.(\d+)(?:\s*[–-]\s*(\d+))?$/); // 1.3-14 | 5.1
      const soNum = peca.match(/^(\d+)(?:\s*[–-]\s*(\d+))?$/); // 24 | 33-34 | 16
      if (cruz) { c = +cruz[1]; de = +cruz[2]; cf = +cruz[3]; ate = +cruz[4]; }
      else if (comCap) { c = +comCap[1]; de = +comCap[2]; cf = c; ate = comCap[3] ? +comCap[3] : de; }
      else if (soNum && UM_CAPITULO.has(livro)) { c = 1; de = +soNum[1]; cf = 1; ate = soNum[2] ? +soNum[2] : de; }
      else if (soNum && cap != null) { c = cap; de = +soNum[1]; cf = c; ate = soNum[2] ? +soNum[2] : de; }
      else if (soNum) { c = +soNum[1]; cf = c; } // capítulo inteiro ("Salmo 8")
      else throw new Error(`Referência não entendida: "${peca}" em "${texto}"`);
      cap = cf;
      out.push({ livro, cap: c, de, capFim: cf, ate, ref: de ? `${livro} ${c}:${de}` : `${livro} ${c}` });
    }
  }
  return out;
}
